let selectedFiles=[];
function renderSelectedFiles(){const summary=document.getElementById('fileSummary');if(selectedFiles.length===0){summary.textContent='No files selected';return}const names=selectedFiles.slice(0,3).map(f=>f.name || 'file').join(', ');const more=selectedFiles.length>3?' +'+(selectedFiles.length-3)+' more':'';const bytes=selectedFiles.reduce((sum,file)=>sum+file.size,0);summary.textContent=names+more+' ('+fmtBytes(bytes)+')'}
function addFiles(files){selectedFiles=selectedFiles.concat(Array.from(files||[]));renderSelectedFiles()}
async function filePayload(file){return {name:file.name || 'upload',mimeType:file.type || 'application/octet-stream',dataBase64:await fileToBase64(file)}}
async function fileToBase64(file){const buffer=await file.arrayBuffer();const bytes=new Uint8Array(buffer);let binary='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk){binary+=String.fromCharCode(...bytes.subarray(i,i+chunk))}return btoa(binary)}
function isLocalDashboardOrigin(){return ['localhost','127.0.0.1','::1'].includes(location.hostname)}
function microphoneSecureContextMessage(){return 'Microphone access requires HTTPS or localhost. LAN HTTP URLs cannot request microphone permission. Open this dashboard on the same machine via http://127.0.0.1:31878 or serve it over HTTPS.'}
function microphoneBlockedMessage(){return 'Microphone access is blocked for this site. Click the lock/site controls in the browser address bar, allow Microphone, then reload the dashboard.'}
function microphonePromptMessage(){return 'Your browser should show a microphone permission prompt. Choose Allow to start recording, or Deny to keep it blocked.'}
async function microphonePermissionState(){try{if(!navigator.permissions?.query)return'';const status=await navigator.permissions.query({name:'microphone' as PermissionName});return status.state}catch{return''}}
async function ensureMicrophoneRecordingAvailable(){if(!window.isSecureContext&&!isLocalDashboardOrigin())throw new Error(microphoneSecureContextMessage());if(!navigator.mediaDevices?.getUserMedia)throw new Error('Microphone recording is not available in this browser context. Use HTTPS or localhost and a browser with MediaRecorder support.');if(typeof MediaRecorder==='undefined')throw new Error('Voice recording is not supported by this browser.');return await microphonePermissionState()}
function microphoneErrorMessage(error){const name=error instanceof DOMException?error.name:'';if(name==='NotAllowedError'||name==='SecurityError')return !window.isSecureContext&&!isLocalDashboardOrigin()?microphoneSecureContextMessage():'Microphone permission was denied. If the browser no longer asks, click the lock/site controls in the address bar, allow Microphone, then reload the dashboard.';if(name==='NotFoundError'||name==='DevicesNotFoundError')return 'No microphone was found on this device.';if(name==='NotReadableError'||name==='TrackStartError')return 'The microphone is already in use or cannot be opened by the browser.';if(name==='OverconstrainedError'||name==='ConstraintNotSatisfiedError')return 'The selected microphone does not support the requested audio settings.';return error instanceof Error&&error.message?error.message:'Microphone recording failed.'}
function currentAgentSupportsRawAudioAttachments(){return ['pi','hermes','openclaw'].includes(state.snapshot?.session?.agentId||'')}
function currentAgentLabel(){return state.snapshot?.session?.agentLabel||state.snapshot?.session?.agentId||'this agent'}
function attachVoiceFallback(file,attachReason='',skipReason=''){if(currentAgentSupportsRawAudioAttachments()){addFiles([file]);toast(attachReason||'Voice transcription failed; audio attached instead');return}toast(skipReason||('Voice transcription failed; audio was not attached for '+currentAgentLabel()))}
function voiceTranscriptionFailureDetail(error){const message=error instanceof Error?error.message:String(error||'');const first=message.split(/\r?\n/).map(line=>line.trim()).find(Boolean)||'';if(first.includes('Voice messages require a transcription backend'))return'no transcription backend is available';return first?first.slice(0,220):'unknown error'}
function insertPromptTranscript(transcript){const text=String(transcript||'').replace(/^Audio transcript \([^)]*\):\s*/i,'').trim();if(!text){toast('No speech detected');return}const input=document.getElementById('promptInput') as HTMLTextAreaElement|null;if(!input)return;const prefix=input.value.trim()?input.value.replace(/\s*$/,'\n'):"";input.value=prefix+text;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();input.setSelectionRange(input.value.length,input.value.length);toast('Voice transcribed')}
async function transcribeVoiceNote(file){if(!can('prompt.send')){attachVoiceFallback(file,'Permission required: prompt.send; voice note attached instead','Permission required: prompt.send; voice note was not attached for '+currentAgentLabel());return}if(!can('files.write')){toast('Permission required: files.write');return}const btn=document.getElementById('recordBtn') as HTMLButtonElement|null;if(btn){btn.disabled=true;btn.textContent='Transcribing...'}try{const payload=await filePayload(file);const r=await api('/api/prompt/upload',{method:'POST',body:JSON.stringify({text:'',correlationId:createWebCorrelationId(),transcribeOnly:true,files:[payload]})});insertPromptTranscript(r.transcript||'')}catch(error){const detail=voiceTranscriptionFailureDetail(error);attachVoiceFallback(file,'Voice transcription failed; audio attached instead ('+detail+')','Voice transcription failed; audio was not attached for '+currentAgentLabel()+' ('+detail+')')}finally{if(btn){btn.disabled=false;btn.textContent='Record voice'}}}
document.getElementById('fileInput').onchange=e=>{if(!can('files.write')){toast('Permission required: files.write');return}addFiles(e.target.files)};
document.getElementById('clearFilesBtn').onclick=()=>{selectedFiles=[];document.getElementById('fileInput').value='';renderSelectedFiles()};
document.addEventListener('paste',e=>{const files=Array.from(e.clipboardData?.files||[]);if(files.length){if(!can('files.write')){toast('Permission required: files.write');return}addFiles(files);toast('Pasted '+files.length+' file(s)')}});
document.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('drop-active')});
document.addEventListener('dragleave',()=>document.body.classList.remove('drop-active'));
document.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('drop-active');const files=Array.from(e.dataTransfer?.files||[]);if(files.length){if(!can('files.write')){toast('Permission required: files.write');return}addFiles(files);toast('Added '+files.length+' dropped file(s)')}});
document.getElementById('promptInput').addEventListener('keydown',e=>{if(e.key!=='Enter'||e.isComposing)return;const input=e.currentTarget as HTMLTextAreaElement;if(e.ctrlKey){e.preventDefault();const start=input.selectionStart??input.value.length;const end=input.selectionEnd??start;input.setRangeText('\n',start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));return}e.preventDefault();(document.getElementById('promptForm') as HTMLFormElement|null)?.requestSubmit()});
function submittedPromptDisplayText(text:string,files:File[]){if(text)return text;return files.length?files.map(file=>file.name||'attachment').join(', '):''}
function appendSubmittedPromptMessage(text:string,files:File[],correlationId:string){const display=submittedPromptDisplayText(text,files);if(!display)return;const timestamp=new Date().toISOString();upsertOptimisticChatMessage({id:'optimistic-'+correlationId,role:'user',source:'web',timestamp,text:display,correlationId,meta:files.length?[files.length+' attachment'+(files.length===1?'':'s')]:undefined});const selector='.message[data-correlation-id="'+cssEscape(correlationId)+'"]';if(!document.querySelector(selector)){appendMessage('user',display,{correlationId,meta:files.length?[files.length+' attachment'+(files.length===1?'':'s')]:undefined,forceScroll:true})}setLocalTurnFromCurrentChat(timestamp);startChatHistoryFollowup();renderChatWorkingIndicator();renderSessionControls();renderChatTabs()}
document.getElementById('promptForm').onsubmit=e=>safe(async()=>{e.preventDefault();const input=document.getElementById('promptInput');const text=input.value.trim();if(/^\/mirror\b/i.test(text)){if(selectedFiles.length){toast('/mirror cannot be sent with attachments');return}const argument=text.replace(/^\/mirror\b/i,'').trim();if(argument&&!can('settings.write')){toast('Permission required: settings.write');return}if(!argument&&!can('sessions.read')){toast('Permission required: sessions.read');return}input.value='';saveActiveChatTabDraft();const data=argument?await setMirrorPreference(argument):await loadMirrorPreference();appendMessage('system',data?.response?.plain||('CLI mirroring: '+(data?.mode||'-')));return}if(!can('prompt.send')){toast('Permission required: prompt.send');return}if(selectedFiles.length&&!can('files.write')){toast('Permission required: files.write');return}if(!text&&selectedFiles.length===0)return;const files=selectedFiles;const correlationId=createWebCorrelationId();input.value='';saveActiveChatTabDraft();selectedFiles=[];document.getElementById('fileInput').value='';renderSelectedFiles();const payloadFiles=files.length?await Promise.all(files.map(filePayload)):[];const eventStreamReconnected=syncChatEventStreamForActiveContext();if(eventStreamReconnected)await new Promise(resolve=>setTimeout(resolve,150));appendSubmittedPromptMessage(text,files,correlationId);try{const r=files.length?await api('/api/prompt/upload',{method:'POST',body:JSON.stringify({text,correlationId,files:payloadFiles})}):await api('/api/prompt',{method:'POST',body:JSON.stringify({text,correlationId})});if(r.transcribeOnly){removeChatMessageForCorrelation(correlationId);appendMessage('system','Transcribed audio:\n'+(r.transcript||'(empty)'))}else if(r.queued){removeChatMessageForCorrelation(correlationId);appendQueuedMessage(r.queueId,r.correlationId||correlationId)}else if(r.correlationId&&r.correlationId!==correlationId){removeChatMessageForCorrelation(correlationId);appendSubmittedPromptMessage(text,files,r.correlationId)}}catch(error){removeChatMessageForCorrelation(correlationId);throw error}},e);
document.getElementById('newSessionBtn').onclick=()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}openNewSessionDialog()};
document.getElementById('syncBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const r=await api('/api/sync',{method:'POST'});toast(r.changed?'Synced: '+(r.changedFields||[]).join(', '):'Already in sync');loadBootstrap()});
