document.getElementById('clearChatBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}if(confirm('Clear chat history for the current thread?')){const r=await api('/api/chat/history',{method:'DELETE'});renderChatMessages(r.messages||[]);toast('Removed '+r.removed+' messages')}});
document.getElementById('abortBtn').onclick=()=>safe(async()=>{if(!can('prompt.abort')){toast('Permission required: prompt.abort');return}await api('/api/abort',{method:'POST'});clearCurrentChatWorkingState();renderChatWorkingIndicator();renderSessionControls();renderChatTabs();safe(loadActiveSessions);toast('Abort sent')});
document.getElementById('recordBtn').onclick=()=>safe(async()=>{if(!can('files.write')){toast('Permission required: files.write');return}const btn=document.getElementById('recordBtn');if(state.mediaRecorder&&state.mediaRecorder.state==='recording'){state.mediaRecorder.stop();btn.textContent='Transcribing...';return}let stream;try{const permission=await ensureMicrophoneRecordingAvailable();if(permission==='prompt')toast(microphonePromptMessage(),{duration:7000});stream=await navigator.mediaDevices.getUserMedia({audio:true})}catch(error){toast(microphoneErrorMessage(error),{duration:10000});return}state.recordedChunks=[];state.mediaRecorder=new MediaRecorder(stream);state.mediaRecorder.ondataavailable=e=>{if(e.data.size>0)state.recordedChunks.push(e.data)};state.mediaRecorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(state.recordedChunks,{type:'audio/webm'});if(blob.size===0){toast('No audio recorded');btn.textContent='Record voice';return}transcribeVoiceNote(new File([blob],'voice-note.webm',{type:'audio/webm'}))};state.mediaRecorder.start();btn.textContent='Stop recording'});
function renderMirrorPreference(data){if(!data)return;state.webMirror=data;if(state.currentPage==='chat')renderSessionControls()}
