function val(id){return document.getElementById(id).value.trim()}
function activeAgentId(){return state.snapshot?.session?.agentId||''}
function shortMiddle(value,edge=6,max=15){const text=String(value??'');if(text.length<=max)return text;return text.slice(0,edge)+'...'+text.slice(-edge)}
function sessionRelativeTimeHtml(timestamp){return '<span class="session-age" data-session-age-at="'+attr(timestamp||'')+'" title="'+attr(fmtDate(timestamp))+'">'+esc(fmtSessionAge(timestamp))+'</span>'}
function sessionAgeHtml(s){return sessionRelativeTimeHtml(s.createdAt||s.updatedAt)}
function sessionCell(label,html,cls=''){return '<td data-label="'+attr(label)+'"'+(cls?' class="'+cls+'"':'')+'>'+html+'</td>'}
function sessionModeBadge(s){const mode=s.workspaceMode||'attached';const label=mode==='worktree'?'Worktree':mode==='shared'?'Shared':'Attached';const title=s.worktree?('Branch: '+s.worktree.branchName+' / Base: '+s.worktree.baseSha):mode;return '<span class="adapter-status '+(mode==='worktree'?'enabled':mode==='shared'?'planned':'disabled')+'" title="'+attr(title)+'">'+esc(label)+'</span>'}
function renderSessionRow(s){const title=s.title||s.firstUserMessage||s.id;const sessionName=String(s.sessionName||'').trim();const threadLabel=sessionName||shortMiddle(s.id);const threadTitle=sessionName?('Copy thread ID: '+s.id):s.id;const thread='<button type="button" class="copy-id" data-copy-id="'+attr(s.id)+'" title="'+attr(threadTitle)+'">'+esc(short(threadLabel,80))+'</button>';const actions='<div class="data-table-actions"><button data-switch="'+attr(s.id)+'"'+disabledAttr('sessions.write')+'>Switch</button><button class="secondary" data-session-detail="'+attr(s.id)+'" data-session-agent="'+attr(s.agentId||'')+'">Details</button></div>';return '<tr>'+sessionCell('Updated',sessionRelativeTimeHtml(s.updatedAt),'updated-cell')+sessionCell('Title','<span class="truncate-cell" title="'+attr(title)+'">'+esc(short(title,120))+'</span>','primary-cell')+sessionCell('Thread ID',thread,'thread-cell')+sessionCell('Workspace','<span class="truncate-cell" title="'+attr(s.cwd||'')+'">'+esc(short(s.cwd||'-',120))+'</span>','workspace-cell')+sessionCell('Mode',sessionModeBadge(s),'optional-model')+sessionCell('Agent',esc(s.agentLabel||s.agentId||'-'),'optional-agent')+sessionCell('Model','<span class="truncate-cell" title="'+attr(s.model||'')+'">'+esc(short(s.model||'-',64))+'</span>','optional-model')+sessionCell('Age',sessionAgeHtml(s),'age-cell')+sessionCell('Actions',actions,'actions-cell')+'</tr>'}
