function bindSessionsTable(root=document){startSessionAgeCounter();root.querySelectorAll('[data-copy-id]').forEach(b=>b.onclick=()=>copyText(b.dataset.copyId||'','Thread ID copied'));root.querySelectorAll('[data-switch]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const session=(state.currentSessions||[]).find(item=>item.id===b.dataset.switch);const sessionName=String(session?.sessionName||'');await openChatSession({peerId:state.selectedPeer||'local',peerName:headerTargetName(state.selectedPeer||'local'),agentId:activeAgentId(),agentLabel:activeAgentId(),threadId:String(b.dataset.switch||''),sessionName,title:String(sessionName||session?.title||session?.firstUserMessage||b.dataset.switch||''),workspace:String(session?.cwd||''),model:String(session?.model||'')},{navigate:state.currentPage==='chat'})}));root.querySelectorAll('[data-session-detail]').forEach(b=>b.onclick=()=>safe(()=>loadSessionDetail(b.dataset.sessionDetail,b.dataset.sessionAgent)));applyPermissions()}
async function loadSessions(reset=true,agentId=''){if(reset)sessionsPager.reset();const expectedAgent=agentId||activeAgentId();const requestId=++state.sessionsRequestId;setLoading('sessionsList','Loading '+(expectedAgent||'agent')+' sessions...');const q=document.getElementById('sessionSearch').value||'';const data=await api('/api/sessions',{query:{query:q,page:sessionsPager.page,limit:sessionsPager.pageSize,agent:expectedAgent||undefined}});if(requestId!==state.sessionsRequestId||expectedAgent!==activeAgentId())return;state.currentSessions=data.sessions||[];renderSessionsTable(data.sessions||[]);sessionsPager.render(data.pagination||{})}
