function renderWorktreeRows(records){if(!records.length)return '<div class="item">No session worktrees yet.</div>';const rows=records.map(r=>{const checkbox='<input type="checkbox" data-worktree-select="'+attr(r.id)+'" '+(isWorktreeReviewSelected(r.id)?'checked ':'')+(r.commitSha?'':'disabled')+'>';const thread=r.threadId?'<button type="button" class="copy-id" data-copy-id="'+attr(r.threadId)+'" title="'+attr(r.threadId)+'">'+esc(shortMiddle(r.threadId))+'</button>':'-';const status='<span class="adapter-status '+(r.statusText==='dirty'?'planned':r.statusText==='merged'?'enabled':r.statusText.includes('conflict')?'disabled':'')+'">'+esc(r.statusText)+'</span>';const actions='<div class="data-table-actions"><button data-worktree-diff="'+attr(r.id)+'">Diff</button><button class="secondary" data-worktree-update="'+attr(r.id)+'"'+disabledAttr('sessions.write')+'>Update</button><button data-worktree-commit="'+attr(r.id)+'"'+disabledAttr('sessions.write')+'>Commit</button><button class="secondary" data-worktree-remove="'+attr(r.id)+'"'+disabledAttr('sessions.write')+'>Remove</button></div>';return '<tr><td data-label="Select">'+checkbox+'</td><td data-label="Status">'+status+'</td><td data-label="Thread ID">'+thread+'</td><td data-label="Branch"><span class="truncate-cell" title="'+attr(r.branchName)+'">'+esc(short(r.branchName,80))+'</span></td><td data-label="Path"><span class="truncate-cell" title="'+attr(r.worktreePath)+'">'+esc(short(r.worktreePath,120))+'</span></td><td data-label="Base"><code title="'+attr(r.baseSha)+'">'+esc(shortMiddle(r.baseSha,7,17))+'</code></td><td data-label="Commit"><code title="'+attr(r.commitSha||'')+'">'+esc(r.commitSha?shortMiddle(r.commitSha,7,17):'-')+'</code></td><td data-label="Actions" class="actions-cell">'+actions+'</td></tr>'}).join('');return '<div class="data-table-wrap"><table class="data-table sessions-table worktrees-table"><thead><tr><th></th><th>Status</th><th>Thread ID</th><th>Branch</th><th>Path</th><th>Base</th><th>Commit</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+rows+'</tbody></table></div>'}
function integrationStatusClass(status){if(status==='merged'||status==='applied')return'enabled';if(status==='conflict'||status==='failed')return'disabled';return'planned'}
function renderWorktreeIntegrations(runs){const target=document.getElementById('worktreeIntegrations');if(!target)return;const list=(runs||[]).slice(0,12);if(!list.length){target.innerHTML=uiEmpty('No integration runs yet.');return}target.innerHTML='<div class="data-table-wrap"><table class="data-table worktree-integrations-table"><thead><tr><th>Updated</th><th>Branch</th><th>Status</th><th>Target</th><th>Path</th><th>Commits</th><th>Resolved</th><th>Error</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+list.map(run=>{const commits=run.mergedCommitShas||run.sourceCommits||[];const resolved=run.resolvedConflicts||[];const targetBranch=run.targetBranch||run.baseBranch||'-';const actions=run.status==='merged'?'<div class="data-table-actions"><button data-worktree-integration-finalize="'+attr(run.id)+'"'+disabledAttr('sessions.write')+'>Finalize</button></div>':run.status==='applied'?'<small title="'+attr(run.appliedCommitSha||'')+'">Applied</small>':'-';return '<tr>'+sessionCell('Updated',sessionRelativeTimeHtml(run.updatedAt),'updated-cell')+sessionCell('Branch','<span class="truncate-cell" title="'+attr(run.branchName||'-')+'">'+esc(short(run.branchName||'-',120))+'</span>','primary-cell')+sessionCell('Status','<span class="adapter-status '+integrationStatusClass(run.status)+'">'+esc(run.status)+'</span>','status-cell')+sessionCell('Target','<span class="truncate-cell" title="'+attr(targetBranch)+'">'+esc(short(targetBranch,80))+'</span>')+sessionCell('Path','<span class="truncate-cell" title="'+attr(run.worktreePath||'-')+'">'+esc(short(run.worktreePath||'-',140))+'</span>')+sessionCell('Commits','<span class="truncate-cell" title="'+attr(commits.join(', ')||'-')+'">'+esc(commits.length||'-')+'</span>')+sessionCell('Resolved','<span class="truncate-cell" title="'+attr(resolved.join(', ')||'-')+'">'+esc(resolved.length||'-')+'</span>')+sessionCell('Error','<span class="truncate-cell '+(run.lastError?'error':'')+'" title="'+attr(run.lastError||'-')+'">'+esc(short(run.lastError||'-',180))+'</span>')+sessionCell('Actions',actions,'actions-cell')+'</tr>'}).join('')+'</tbody></table></div>';startSessionAgeCounter()}
async function loadWorktrees(){if(!can('sessions.read'))return;setLoading('worktreesList','Loading worktrees...');const data=await api('/api/sessions/worktrees');state.worktrees=data;renderWorktreeWarnings(data.sharedWarnings||[]);document.getElementById('worktreesList').innerHTML=renderWorktreeRows(data.records||[]);renderWorktreeIntegrations(data.integrations||[]);bindWorktreeReviewCenter();document.querySelectorAll('[data-copy-id]').forEach(b=>b.onclick=()=>copyText(b.dataset.copyId||'','Thread ID copied'));document.querySelectorAll('[data-worktree-diff]').forEach(b=>b.onclick=()=>safe(()=>showWorktreeDiff(b.dataset.worktreeDiff)));document.querySelectorAll('[data-worktree-update]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const result=await api('/api/sessions/worktrees/'+encodeURIComponent(b.dataset.worktreeUpdate)+'/update',{method:'POST',body:JSON.stringify({})});toast(result.record?.status==='conflict'?'Worktree update has conflicts':result.rebased?'Worktree updated from base':'Worktree already current');loadWorktrees()}));document.querySelectorAll('[data-worktree-commit]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const message=prompt('Commit message','NordRelay session '+b.dataset.worktreeCommit)||undefined;const result=await api('/api/sessions/worktrees/'+encodeURIComponent(b.dataset.worktreeCommit)+'/commit',{method:'POST',body:JSON.stringify({message})});toast(result.clean?'Worktree clean':'Worktree committed');loadWorktrees()}));document.querySelectorAll('[data-worktree-remove]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}if(confirm('Remove this worktree?')){await api('/api/sessions/worktrees/'+encodeURIComponent(b.dataset.worktreeRemove),{method:'DELETE',body:JSON.stringify({force:true})});toast('Worktree removed');loadWorktrees()}}));document.querySelectorAll('[data-worktree-integration-finalize]').forEach(b=>b.onclick=()=>safe(()=>openFinalizeIntegrationDialog(b.dataset.worktreeIntegrationFinalize)));applyPermissions()}

function openFinalizeIntegrationDialog(id){if(!can('sessions.write')){toast('Permission required: sessions.write');return}const run=(state.worktrees?.integrations||[]).find(item=>item.id===id);if(!run){toast('Integration run not found');return}const target=run.targetBranch||run.baseBranch||'';adminDialog('Finalize integration','<div class="full-span"><p>Apply the integration branch back into the original repository. The repository must be on the target branch and have a clean working tree.</p><div class="form-grid"><label>Target branch<input id="finalizeTargetBranch" value="'+attr(target)+'" placeholder="current branch"></label><label class="checkbox"><input id="finalizeRemoveIntegration" type="checkbox" checked> Remove integration worktree</label><label class="checkbox"><input id="finalizeRemoveSources" type="checkbox"> Remove source worktrees</label><label class="checkbox"><input id="finalizeDeleteBranch" type="checkbox"> Delete integration branch after apply</label></div><small>Branch: '+esc(run.branchName||'-')+'</small></div>',async()=>{const result=await api('/api/sessions/worktrees/integrations/'+encodeURIComponent(id)+'/finalize',{method:'POST',body:JSON.stringify({targetBranch:val('finalizeTargetBranch')||undefined,removeIntegrationWorktree:document.getElementById('finalizeRemoveIntegration').checked,removeSourceWorktrees:document.getElementById('finalizeRemoveSources').checked,deleteIntegrationBranch:document.getElementById('finalizeDeleteBranch').checked})});const warnings=result.run?.cleanup?.warnings||[];toast('Integration applied'+(warnings.length?' with '+warnings.length+' cleanup warning(s)':''),{duration:warnings.length?9000:4000});await loadWorktrees()},{submitText:'Finalize',reloadAccess:false})}

async function showWorktreeDiff(id){const result=await api('/api/sessions/worktrees/'+encodeURIComponent(id)+'/diff');const fileList=(result.files||[]).map(f=>'<span class="adapter-status '+worktreeStatusClass(f.status)+'">'+esc(f.status)+'</span> <span class="truncate-cell" title="'+attr(f.path)+'">'+esc(short(f.path,180))+'</span>').join('')||'No changed files.';const structured=(result.structuredFiles||[]).map(f=>'<details class="worktree-diff-file" open><summary>'+esc(f.path)+' <small>+'+esc(f.additions||0)+' / -'+esc(f.deletions||0)+'</small></summary>'+splitDiff(structuredDiffToUnified(f))+'</details>').join('');adminDialog('Worktree diff','<div class="full-span"><div class="worktree-file-list">'+fileList+'</div>'+(structured||splitDiff(result.diff||''))+'<details><summary>Unified diff</summary><pre class="artifact-diff-pre">'+highlightDiff(result.diff||'No diff.')+'</pre></details>'+(result.truncated?'<small>Diff truncated.</small>':'')+'</div>',async()=>{}, {submitText:'Close',reloadAccess:false})}
function worktreeSourceName(source,preview){const id=typeof source==='string'?source:source?.id;const found=(preview.sourceWorktrees||[]).find(s=>s.id===id);return found?.branchName||found?.threadId||id||'-'}
function worktreeConflictSourceOptions(item,preview){const sources=item.sourceWorktrees||[];return '<select data-worktree-resolution-source="'+attr(item.path)+'">'+sources.map(source=>{const id=typeof source==='string'?source:source.id;return '<option value="'+attr(id)+'">'+esc(worktreeSourceName(id,preview))+'</option>'}).join('')+'</select>'}
function worktreeResolutionControls(item,preview){if(item.risk==='none')return '-';return '<div class="worktree-resolution-controls"><select data-worktree-resolution-path="'+attr(item.path)+'"><option value="auto">Stop for manual Git conflict</option><option value="ours">Keep integration/base side</option><option value="theirs">Use selected source</option><option value="both">Combine all source versions</option><option value="manual">Use manual content</option></select>'+worktreeConflictSourceOptions(item,preview)+'<textarea data-worktree-resolution-content="'+attr(item.path)+'" rows="3" placeholder="Manual file content"></textarea></div>'}
function worktreeVersionPreviewBlock(version){if(!version)return'';const title=(version.label||version.branchName||version.worktreeId||'version')+(version.truncated?' · truncated':'');const body=version.content!==undefined?'<pre class="artifact-diff-pre">'+esc(version.content||'')+'</pre>':'<small>'+esc(version.unavailable||'Unavailable')+'</small>';return '<details class="worktree-version-preview"><summary>'+esc(title)+'</summary>'+body+'</details>'}
function worktreeVersionPreviews(item){const blocks=[worktreeVersionPreviewBlock(item.baseContent)].concat((item.sourceVersions||[]).map(worktreeVersionPreviewBlock)).join('');return blocks?'<details class="worktree-conflict-versions"><summary>File versions</summary>'+blocks+'</details>':''}
function worktreeConflictReviewTable(preview){const items=preview.conflictReview||[];if(!items.length)return uiEmpty('No changed files in selected worktrees.');return '<div class="data-table-wrap"><table class="data-table worktree-conflict-table"><thead><tr><th>Risk</th><th>File</th><th>Status</th><th>Sources</th><th>Resolution</th><th>Recommendation</th></tr></thead><tbody>'+items.map(item=>{const sourceNames=(item.sourceWorktrees||[]).map(source=>worktreeSourceName(source,preview)).join(', ');return '<tr>'+sessionCell('Risk','<span class="adapter-status '+(item.risk==='none'?'enabled':item.risk==='same-file'?'planned':'disabled')+'">'+esc(item.risk)+'</span>','status-cell')+sessionCell('File','<span class="truncate-cell" title="'+attr(item.path)+'">'+esc(short(item.path,180))+'</span>'+worktreeVersionPreviews(item),'primary-cell')+sessionCell('Status',esc(item.status||'-'))+sessionCell('Sources','<span class="truncate-cell" title="'+attr(sourceNames)+'">'+esc(short(sourceNames||'-',160))+'</span>')+sessionCell('Resolution',worktreeResolutionControls(item,preview),'actions-cell')+sessionCell('Recommendation','<span class="truncate-cell" title="'+attr(item.recommendation||'-')+'">'+esc(short(item.recommendation||'-',220))+'</span>')+'</tr>'}).join('')+'</tbody></table></div>'}
function worktreePreviewSourcesTable(preview){const sources=preview.sourceWorktrees||[];if(!sources.length)return'';return '<h3 class="table-section-title">Sources</h3><div class="data-table-wrap"><table class="data-table worktree-preview-sources-table"><thead><tr><th>Branch</th><th>Thread</th><th>Status</th><th>Path</th><th>Commit</th></tr></thead><tbody>'+sources.map(s=>'<tr>'+sessionCell('Branch','<span class="truncate-cell" title="'+attr(s.branchName||'-')+'">'+esc(short(s.branchName||'-',120))+'</span>','primary-cell')+sessionCell('Thread',s.threadId?'<button type="button" class="copy-id" data-copy-id="'+attr(s.threadId)+'" title="'+attr(s.threadId)+'">'+esc(shortMiddle(s.threadId))+'</button>':'-')+sessionCell('Status','<span class="adapter-status '+(s.statusText==='clean'?'enabled':s.statusText?.includes('conflict')?'disabled':'planned')+'">'+esc(s.statusText||'-')+'</span>','status-cell')+sessionCell('Path','<span class="truncate-cell" title="'+attr(s.worktreePath||'-')+'">'+esc(short(s.worktreePath||'-',140))+'</span>')+sessionCell('Commit','<code title="'+attr(s.commitSha||'')+'">'+esc(s.commitSha?shortMiddle(s.commitSha,7,17):'-')+'</code>')+'</tr>').join('')+'</tbody></table></div>'}
function worktreeIntegrationPreviewHtml(preview){const warnings=(preview.warnings||[]).length?'<div class="peer-warning full-span"><strong>Warnings</strong>'+(preview.warnings||[]).map(w=>'<small>'+esc(w)+'</small>').join('')+'</div>':'<div class="item"><strong>Ready to integrate</strong><small>No warnings reported by the preview.</small></div>';return '<div class="full-span">'+warnings+worktreePreviewSourcesTable(preview)+'<h3 class="table-section-title">Conflict review</h3>'+worktreeConflictReviewTable(preview)+'</div>'}

function selectedWorktreeIds(){return [...document.querySelectorAll('[data-worktree-select]:checked')].map(el=>el.dataset.worktreeSelect).filter(Boolean)}
function collectWorktreeResolutions(root){const scope=root||document;return [...scope.querySelectorAll('[data-worktree-resolution-path]')].map(select=>{const path=select.dataset.worktreeResolutionPath;const choice=select.value;return {path,choice,sourceWorktreeId:scope.querySelector('[data-worktree-resolution-source="'+cssEscape(path)+'"]')?.value||undefined,content:scope.querySelector('[data-worktree-resolution-content="'+cssEscape(path)+'"]')?.value||undefined}}).filter(item=>item.path&&item.choice&&item.choice!=='auto')}
document.querySelectorAll('[data-session-tab]').forEach(b=>b.onclick=()=>switchSessionTab(b.dataset.sessionTab));
document.getElementById('reloadWorktreesBtn').onclick=()=>safe(loadWorktrees);
document.getElementById('forkWorktreeBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const include=document.getElementById('forkIncludeUncommitted').checked;if(include&&!confirm('Copy tracked diff and untracked files from the current workspace into a new worktree?'))return;const result=await api('/api/sessions/worktrees/fork',{method:'POST',body:JSON.stringify({includeUncommitted:include})});toast('Forked into '+result.record.branchName);await loadBootstrap();await loadWorktrees();if(state.currentPage==='chat')await loadChatHistory({forceScroll:true})});
document.getElementById('integrateWorktreesBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const ids=selectedWorktreeIds();if(!ids.length){toast('Select committed worktrees first');return}const preview=await api('/api/sessions/worktrees/integrate/preview',{method:'POST',body:JSON.stringify({ids})});const risky=(preview.conflictReview||[]).filter(item=>item.risk!=='none');const resolutions=state.worktreeConflictResolutions||[];if((preview.warnings?.length||risky.length)&&!resolutions.length&&!confirm('Integration has '+(preview.warnings?.length||0)+' warning(s) and '+risky.length+' file risk(s). Open Preview to inspect and save resolutions.\n\nContinue without saved resolutions?'))return;const result=await api('/api/sessions/worktrees/integrate',{method:'POST',body:JSON.stringify({ids,resolutions})});toast(result.run.status==='merged'?'Integration branch created'+(result.run.resolvedConflicts?.length?' with '+result.run.resolvedConflicts.length+' resolved conflict(s)':''):'Integration '+result.run.status,{duration:8000});state.worktreeConflictResolutions=[];loadWorktrees()});
document.getElementById('previewWorktreeIntegrationBtn').onclick=()=>safe(async()=>{const ids=selectedWorktreeIds();if(!ids.length){toast('Select committed worktrees first');return}await openWorktreeResolverPreview(ids)});
const exportWorktreePatchBtn=document.getElementById('exportWorktreePatchBtn');
if(exportWorktreePatchBtn)exportWorktreePatchBtn.onclick=()=>safe(async()=>{const ids=selectedWorktreeIds();if(!ids.length){toast('Select committed worktrees first');return}await exportWorktreeBundle(ids)});
document.getElementById('cleanupWorktreesBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const result=await api('/api/sessions/worktrees/cleanup',{method:'POST',body:JSON.stringify({})});toast('Cleanup removed '+(result.removedRecords||[]).length+' stale record(s)');loadWorktrees()});
function usageRows(rows){return (rows||[]).map(row=>{if(Array.isArray(row))return [row[0],row[1]];const text=String(row);const index=text.indexOf(':');return index>0?[text.slice(0,index),text.slice(index+1).trim()]:[text,'']})}
function detailSection(key,title,count,body='',open=false){return '<details class="session-detail-section" data-session-detail-section="'+attr(key)+'" '+(open?'open':'')+'><summary>'+esc(title+' ('+count+')')+'</summary>'+(body||uiEmpty('No entries.'))+'</details>'}
function sessionNameForm(name){return '<form id="sessionNameForm" class="session-name-form"><label>Session name <input id="sessionNameInput" maxlength="30" value="'+attr(name||'')+'" placeholder="Optional, max 30 characters"></label><div class="row"><button type="submit"'+disabledAttr('sessions.write')+'>Save</button><button type="button" id="clearSessionNameBtn" class="secondary"'+disabledAttr('sessions.write')+'>Clear</button></div><small id="sessionNameCounter">'+esc(String((name||'').length))+'/30</small></form>'}
function bindSessionNameForm(threadId,agentId='',peerId=state.sessionDetailPeerId||state.selectedPeer||'local'){const form=document.getElementById('sessionNameForm');const input=document.getElementById('sessionNameInput');const counter=document.getElementById('sessionNameCounter');const clear=document.getElementById('clearSessionNameBtn');if(!form||!input)return;const updateCounter=()=>{if(counter)counter.textContent=String((input.value||'').replace(/\s+/g,' ').trim().length)+'/30'};input.oninput=updateCounter;const save=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const name=(input.value||'').replace(/\s+/g,' ').trim();if(name.length>30){toast('Session name must be 30 characters or fewer');return}await headerTargetRequest(peerId,'/api/sessions/name',{method:'POST',body:JSON.stringify({threadId,agentId:agentId||undefined,name})});toast(name?'Session name saved':'Session name cleared');await loadBootstrap();await loadActiveSessions();await loadSessionDetail(threadId,agentId,{peerId})});form.onsubmit=e=>{e.preventDefault();save()};if(clear)clear.onclick=()=>{input.value='';updateCounter();save()};updateCounter();applyPermissions()}
function sessionDetailText(value,max=96,middle=false){const text=String(value??'').trim();if(!text)return'';const display=middle?shortMiddle(text,12,max):short(text,max);return '<span class="session-meta-value" title="'+attr(text)+'">'+esc(display)+'</span>'}
function sessionDetailCopy(value,label='Copied',max=96,middle=false){const text=String(value??'').trim();if(!text)return'';const display=middle?shortMiddle(text,12,max):short(text,max);return '<button type="button" class="copy-id session-meta-copy" data-copy-value="'+attr(text)+'" data-copy-label="'+attr(label)+'" title="'+attr(text)+'">'+esc(display)+'</button>'}
function sessionDetailBadge(value,status='enabled'){const text=String(value??'').trim();return text?'<span class="adapter-status '+attr(status)+'">'+esc(text)+'</span>':''}
function sessionMetaRow(label,body){return body?'<div class="session-meta-row"><span>'+esc(label)+'</span><strong>'+body+'</strong></div>':''}
function sessionMetaSection(title,rows,cls=''){const filtered=rows.filter(Boolean);const body=filtered.join('');if(!body)return'';if(cls==='session-meta-advanced')return'<details class="session-meta-section session-meta-advanced"><summary>'+esc(title+' ('+filtered.length+')')+'</summary>'+body+'</details>';return '<section class="session-meta-section '+attr(cls)+'"><h3>'+esc(title)+'</h3>'+body+'</section>'}
function sessionDetailNodeLabel(peerId=state.selectedPeer||'local'){return peerId&&peerId!=='local'?headerTargetName(peerId):''}
function sessionDetailHeader(d,threadId,peerId=state.selectedPeer||'local'){const r=d.record||{},a=d.active||{};const title=String(d.sessionName||r.title||r.firstUserMessage||'Session detail');const subtitle=[sessionDetailNodeLabel(peerId),a.agentLabel||r.agentLabel||a.agentId||r.agentId,a.model||r.model,a.workspace||r.cwd].filter(Boolean).join(' · ');return '<div class="session-detail-header"><div><h2>'+esc(short(title,120))+'</h2>'+(subtitle?'<small>'+esc(short(subtitle,180))+'</small>':'')+'</div><div class="session-detail-header-actions">'+sessionDetailCopy(threadId,'Thread ID copied',24,true)+'</div></div>'}
function sessionDetailLayout(d,threadId){const r=d.record||{},a=d.active||{};const workspace=r.cwd||a.workspace;const mode=r.workspaceMode||a.workspaceMode;const worktree=r.worktree||a.worktree||{};const launch=a.launchProfileLabel||a.launchProfileId||r.launchProfileId;const permissions=a.launchProfileBehavior||[a.sandboxMode,a.approvalPolicy].filter(Boolean).join(' / ');const fast=a.fastMode===true?'on':a.fastMode===false?'off':'';const usage=usageRows(d.usageRows).map(row=>sessionMetaRow(row[0],sessionDetailText(row[1],100)));const identity=[sessionMetaRow('Thread',sessionDetailCopy(threadId,'Thread ID copied',28,true)),sessionMetaRow('Agent',sessionDetailBadge(a.agentLabel||r.agentLabel||a.agentId||r.agentId,'enabled')),sessionMetaRow('Title',sessionDetailText(r.title||r.firstUserMessage,140)),sessionMetaRow('Name',sessionDetailText(d.sessionName,80))];const runtime=[sessionMetaRow('Model',sessionDetailText(a.model||r.model,90)),sessionMetaRow('Reasoning / Fast',sessionDetailText([a.reasoningEffort||r.reasoningEffort,fast].filter(Boolean).join(' / '),80)),sessionMetaRow('Launch',sessionDetailText(launch,90)),sessionMetaRow('Permissions',sessionDetailText(permissions,110)),sessionMetaRow('Workspace mode',mode?sessionDetailBadge(mode,mode==='worktree'?'enabled':mode==='shared'?'planned':'disabled'):'')];const workspaceRows=[sessionMetaRow('Workspace',sessionDetailCopy(workspace,'Workspace path copied',80,true)),sessionMetaRow('Worktree',sessionDetailText(worktree.branchName||worktree.id,120)),sessionMetaRow('Worktree path',sessionDetailCopy(worktree.worktreePath||worktree.path,'Worktree path copied',80,true))];const timing=[sessionMetaRow('Created',r.createdAt?sessionRelativeTimeHtml(r.createdAt):''),sessionMetaRow('Updated',sessionRelativeTimeHtml(r.updatedAt||a.updatedAt)),sessionMetaRow('Last activity',sessionRelativeTimeHtml(a.updatedAt||r.updatedAt))];const advanced=[sessionMetaRow('Session path',sessionDetailCopy(r.sessionPath||a.sessionPath,'Session path copied',80,true)),sessionMetaRow('Base SHA',sessionDetailText(worktree.baseSha,90,true)),sessionMetaRow('Worktree ID',sessionDetailText(worktree.id,90,true))];return '<div class="session-meta-grid">'+sessionMetaSection('Identity',identity)+sessionMetaSection('Runtime',runtime)+sessionMetaSection('Workspace',workspaceRows)+sessionMetaSection('Usage',usage,'session-meta-usage')+sessionMetaSection('Timing',timing)+sessionMetaSection('Advanced',advanced,'session-meta-advanced')+'</div>'}
function sessionDetailTimestampMs(value){const time=Date.parse(String(value||''));return Number.isFinite(time)?time:0}
function sessionDetailNewestFirst(items){return [...(items||[])].sort((left,right)=>sessionDetailTimestampMs(right.timestamp)-sessionDetailTimestampMs(left.timestamp))}
function sessionDetailTableText(label,value,max=180,cls=''){const text=String(value??'').trim()||'-';return sessionCell(label,'<span class="truncate-cell" title="'+attr(text)+'">'+esc(short(text,max))+'</span>',cls)}
